--   岐阜県美濃市 長：調查時點出缺（沒有任期満了日）
--   静岡県伊東市 長：調查時點出缺（沒有任期満了日）
--   鹿児島県摩川内市：對不到団体コード（原檔寫法不同）
--   沖縄県南城市 議会：任期満了日欄是空的

